-- Official old -> new administrative unit crosswalk, and the marker that makes a
-- migration-seeded row usable as reviewed whole-mapping evidence.
--
-- Source: sunshine-tech/VietnamProvinces (published by that package as the
-- vietnam_provinces._province_conversion_2025 and _ward_conversion_2025 tables, both
-- generated from the pinned file below)
--   repository: https://github.com/sunshine-tech/VietnamProvinces
--   pinned release: v2026.9.0
--   tag commit: 4cc4038d0e89bd8affbda864119c1ab1e0360523
--   data file: dev/seed-data/2025-07/BangChuyendoiĐVHCmoi_cu_khong_merge.csv
--   sha256: 21da94f59a498d03deda1f0882e71f65cd3b7c855bbd6c760ba72f6b6a94ee46
--   source rows: 10,605 body rows = 34 province section headers + 10,571 mapping rows
--   rows seeded: 10,622 = 63 province-level / 5 district-level / 10,554 ward-level
--
-- Vendor boundary: only factual rows are copied here - official numeric codes,
-- the parent link each row states, the official transition note where it is not
-- one of the three plain categories, and the effective date - each row citing
-- the pinned file in source_url. No upstream code, module or transform is used.
-- Upstream declares `license = "GPL-3.0-or-later"` in pyproject.toml and
-- publishes no LICENSE file; the licence question is an open legal item, not a
-- settled one. The current-window units this table maps onto keep their own
-- source from thanglequoc/vietnamese-provinces-database; the two vendors never
-- share one source_url value.
--
-- How a source row becomes a version pair: the legacy unit is resolved by the
-- official ward code against the pre-2025 catalog, the current unit by the
-- official new-ward code against the current catalog, and the legacy province
-- from the district code (Mã QH), never from the file's `Tỉnh cũ` cell, which is
-- wrong on two rows. Every row's effective_on is 2025-07-01, the day the current
-- two-tier catalog opens, and it equals the `to` unit's valid_from; every `from`
-- unit's valid_to is 2025-07-01, so no row links units of the same generation.
--
-- How the relation is derived, one rule per legacy unit over its accepted rows:
--   * two or more distinct `to` units                                   -> partial
--   * exactly one `to` unit and the note is not "toàn bộ" / "Giữ nguyên" -> partial
--   * exactly one `to` unit, note "Đổi tên" or "Đổi loại hình"          -> rename
--   * exactly one `to` unit, note "Nhập toàn bộ" or "Giữ nguyên"        -> whole
-- A single successor is therefore not automatically whole: 00556 Xã Đặng Xá ->
-- 00541 Xã Phù Đổng is `Nhập một phần diện tích`, and it is recorded as partial
-- so it never satisfies the whole-mapping guard. A merged ward whose name
-- changes is not a rename: only the source's own rename notes are renames.
-- "Giữ nguyên" is `whole`, because the unit kept its whole territory; the
-- undisturbed fact stays readable from resolution_notes.
-- Totals over the 10,023 legacy wards with at least one accepted row:
--   whole 9,578 / partial 441 / rename 4; every one of the 63 province-level
--   rows is whole (34 current provinces are formed from 63 legacy ones).
--
-- A district whose tier disappeared but whose wards survive gets no row: its
-- fate is carried by its wards, and a district -> commune row would assert a
-- level change that did not happen. The five island districts that became one
-- đặc khu each get one whole row, the only rows whose two sides differ in level;
-- the source states that transition, so it is not inferred.
--
-- Rejected rather than guessed, and why (17 source rows):
--   * 11 ward rows whose old ward code is absent from the 2025-01-04 snapshot:
--     03980, 03983 and 03984 in Huyện Mộc Châu (123), and 26929, 26953 and
--     27076 twice, plus 27226, 27232, 27367 and 27373 across old Quận Bình
--     Thạnh (765), Phú Nhuận (768), Quận 11 (772) and Quận 6 (775). The two
--     source files enumerate different ward codes there, so no defensible
--     choice exists; the affected legacy wards keep no crosswalk row.
--   * 6 district-level statements with no old ward code: five become the
--     district -> đặc khu rows above, and the sixth - Huyện Kim Sơn (376)
--     "Khu vực bãi bồi ven biển do huyện Kim Sơn quản lý" -> Xã Kim Đông - is
--     rejected because a managed tidal area is not an administrative unit.
-- Recorded as review notes rather than rejections, because the code is
-- authoritative:
--   * 122 rows whose old ward name differs from the snapshot's name at the same
--     code and district under a folded comparison (diacritics, đ/d, case and
--     whitespace normalised). The snapshot's name is kept on the legacy unit;
--     this table only ever stores the unit ids, so no name is overwritten.
--   * 2 rows whose `Tỉnh cũ` cell names the wrong province: 27691 Phường 4 ->
--     27694 Phường Long An says Tiền Giang while district 794 is Long An, and
--     30781 Xã Tiên Hải -> 30781 Xã Tiên Hải says An Giang while district 900
--     is Kiên Giang. Both are resolved through the district code.
--   * 28 of the 10,051 legacy wards carry no row at all, because the table
--     states no successor row this ingest can accept for them:
--     01651, 02482, 03751, 03898, 03913, 03988, 03991, 04003, 04060, 07693,
--     07732, 07744, 16387, 16411, 18448, 20176, 20674, 25102, 25174, 25177,
--     25186, 26935, 26959, 27067, 27217, 27223, 27361, 27379.
--     Coverage is therefore 10,023 of 10,051 legacy wards (99.72%); every one of
--     the 63 legacy provinces carries exactly one row and 5 of 696 legacy
--     districts carry one.
--
-- D1: a migration has no employee to put in verified_by, so a seeded row carries
-- source_attested = true instead and the whole-mapping guard accepts either. The
-- evidence demands are otherwise unchanged: a partial transition still never
-- satisfies official_whole_mapping. The companion migration
-- admin_unit_crosswalks_write_boundary closes the browser write path, because an
-- attested row that an admin can insert or edit from the client would be an
-- unguarded write standing behind a verification.
--
-- Idempotent: every row converges on the (from_unit_id, to_unit_id, effective_on)
-- unique key, so re-applying the migration neither duplicates rows nor changes
-- generated ids. Self-contained: no network fetch, no secret, no external file.

begin;

alter table public.admin_unit_crosswalks
  add column if not exists source_attested boolean not null default false;

comment on column public.admin_unit_crosswalks.source_attested is
  'True only for a row derived from the pinned official conversion table by migration. An employee review sets verified_by instead; either satisfies the whole-mapping guard.';

-- The whole-mapping evidence predicate now accepts a migration-attested row.
create or replace function private.guard_address() returns trigger language plpgsql security definer set search_path='' as $$
declare p public.admin_unit_versions; d public.admin_unit_versions; c public.admin_unit_versions;
begin
  if length(btrim(new.address_text)) not between 1 and 2000 then raise exception 'known address required' using errcode='23514'; end if;
  if new.province_unit_id is not null then
    select * into p from public.admin_unit_versions where id=new.province_unit_id;
    if not found or p.unit_level<>'province' then raise exception 'province mismatch' using errcode='23514'; end if;
  end if;
  if new.district_unit_id is not null then
    select * into d from public.admin_unit_versions where id=new.district_unit_id;
    if not found or d.unit_level<>'district' or d.parent_id is distinct from new.province_unit_id then raise exception 'district mismatch' using errcode='23514'; end if;
  end if;
  if new.commune_unit_id is not null then
    select * into c from public.admin_unit_versions where id=new.commune_unit_id;
    if not found or c.unit_level<>'commune' or c.parent_id is distinct from coalesce(new.district_unit_id,new.province_unit_id) then raise exception 'commune mismatch' using errcode='23514'; end if;
  end if;
  if new.mapping_status='verified' and (tg_op='INSERT' or
    (to_jsonb(new)-array['revision','is_primary']) is distinct from (to_jsonb(old)-array['revision','is_primary'])) then
    if not private.is_reviewer() then raise exception 'reviewer required for mapping' using errcode='42501'; end if;
    if new.format<>'current' or new.province_unit_id is null or new.commune_unit_id is null or new.effective_on is null
      or length(btrim(coalesce(new.mapping_evidence,''))) not between 10 and 2000
      or coalesce(new.source_url,'') !~ '^https?://[^[:space:]]+$' or new.verification_method is null
      or new.effective_on<p.valid_from or (p.valid_to is not null and new.effective_on>=p.valid_to)
      or new.effective_on<c.valid_from or (c.valid_to is not null and new.effective_on>=c.valid_to) then
      raise exception 'valid hierarchy date provenance and property evidence required' using errcode='23514'; end if;
    if new.verification_method='official_whole_mapping' and not exists(
      select 1 from public.admin_unit_crosswalks x join public.property_addresses a on a.commune_unit_id=x.from_unit_id
      where a.property_id=new.property_id and a.format='legacy' and x.to_unit_id=new.commune_unit_id
        and x.relation in ('whole','rename') and x.effective_on<=new.effective_on
        and (x.verified_by is not null or x.source_attested)
    ) then raise exception 'whole mapping evidence required; partial transitions unresolved' using errcode='23514'; end if;
    new.verified_by:=private.employee_id(); new.verified_at:=clock_timestamp();
  end if;
  return new;
end;
$$;

