join public.admin_unit_versions f on f.unit_level='commune' and f.official_code=v.from_code and f.valid_from=date '2025-01-04'
join public.admin_unit_versions t on t.unit_level='commune' and t.official_code=v.to_code and t.valid_from=date '2025-07-01'
on conflict (from_unit_id,to_unit_id,effective_on) do update
  set relation = excluded.relation,
      source_url = excluded.source_url,
      source_attested = excluded.source_attested,
      resolution_notes = excluded.resolution_notes;
-- Guard the seeded evidence itself: the row count is the ingest's own
-- assertion, and no row may link two units of the same generation.
do $$ declare n int; begin
  select count(*) into n from public.admin_unit_crosswalks;
  if n <> 10622 then raise exception 'crosswalk ingest expected 10,622 rows, found %', n; end if;
  if exists (
    select 1 from public.admin_unit_crosswalks x
    join public.admin_unit_versions f on f.id = x.from_unit_id
    join public.admin_unit_versions t on t.id = x.to_unit_id
    where x.effective_on <> date '2025-07-01' or t.valid_from <> x.effective_on
      or f.valid_to is distinct from date '2025-07-01'
  ) then raise exception 'crosswalk row links units outside the legacy/current boundary'; end if;
end $$;

